        float TC = k == 0 ? ( RK_Q >= 3 ? 0.16 : 0.2 ) : 0.5;
        float dk = k == 0 ? tafDens : smoothstep( 0.3, 0.62, tafDens ) * 0.45;
        float res = rkAAf( 1.0 / TC, rkPix * 1.6 );
