        float dep = ( k == 0 ? 0.05 : 0.14 ) * res;         // pit depth (m)
        grad3 += ( rkFU * tf.y + vec3( 0.0, tf.z, 0.0 ) ) * ( dep / TC );
        float z = tf.x * dep;                                 // local depth below the face (m)
