        if ( tf.x > 0.001 && Ln > 0.02 ) {
          vec2 q = oc + Lf * ( z / TC );
          float ex = length( vec2( q.x * 0.72, q.y ) ) / tf.w;
          rkPitSun = min( rkPitSun, mix( 1.0, 0.32, smoothstep( 0.9, 1.1, ex ) ) );
