  rkAlb *= mix( 1.0, 0.8 + 0.4 * rkMot, rkAAf( 1.6, rkPix ) );
  float rkIron = smoothstep( 0.56, 0.8, rkNoise( rkP * 0.75 + 13.0 ) * 0.7 + mix( 0.15, rkNoise( rkP * 3.1 ) * 0.3, rkAAf( 3.1, rkPix ) ) );
  rkIron *= rkAAf( 0.75, rkPix ) * 0.7 + 0.3;
