    float cbId = floor( cbC ), cbF = fract( cbC );
    float cbH = rkHash13( vec3( cbId, rkSeed * 3.0, 7.7 ) );
    float cbOn = step( 0.35, cbH ) * rkSteepF;
    if ( cbOn > 0.01 ) {
