        vec3 c = vec3( li + g, 29.0 );
        float hz = rkHash13( c + 1.9 );
        if ( hz > lDen ) continue;
        vec2 r = g + 0.2 + 0.6 * vec2( rkHash13( c + 0.3 ), rkHash13( c + 4.4 ) ) - lf;
