        vec3 lc = lId < 0.5 ? vec3( 0.43, 0.45, 0.37 ) : ( lId < 0.78 ? vec3( 0.47, 0.5, 0.2 ) : vec3( 0.6, 0.31, 0.07 ) );
        lc *= mix( 0.78, 1.08, smoothstep( 0.35, 0.95, lS ) );
