  rkRough = mix( rkRough, 0.95, clamp( rkMoss + rkDust * 0.5, 0.0, 1.0 ) );
  rkRough *= 1.0 - 0.25 * rkAux.b;
  float rkAO = rkOrm.r * mix( 0.42, 1.0, rkCav ) * mix( 0.55, 1.0, smoothstep( 0.0, 0.55, rkGround ) );
  rkAO *= 1.0 - 0.6 * rkTaf;

