  float rkAn = rkFbm( rkP * 1.1 + 9.0 );
  float rkAlgae = rkUnder * smoothstep( 0.32, 0.68, rkAn + rkN.y * 0.25 + ( 1.0 - smoothstep( 0.2, 1.2, -rkAbove ) ) * 0.2 );
