      float dust = (1.0 - smoothstep(0.0, 0.5, hG)) * 0.4;
      float s = max(sandUp, dust);
      kC = mix(kC, vec3(0.58, 0.49, 0.36), s);
      roughnessFactor = mix(roughnessFactor, 1.0, s);
