  }
  // ---- nail pair over each support (heads, rust bleeding along the grain)
  float kNraw = floor(vKitB.y + 0.5);
  float kNmid = step(127.5, kNraw);
  float kNI = (kNraw - 128.0 * kNmid) * 0.002;
  if (kIsTop > 0.5 && kNI > 0.0) {
    float kNa = mix(kNI, kLen - kNI, kEndSel);
    float kMidSel = kNmid * step(abs(vKitA.x - 0.5 * kLen), abs(vKitA.x - kNa));
    kNa = mix(kNa, 0.5 * kLen, kMidSel);
    kEndSel += 2.0 * kMidSel;
    float kTwo = step(0.055, kHw);
    float kSide = vKitA.y >= 0.0 ? 1.0 : -1.0;
    vec2 kJ = (vec2(kitHash(vec2(kSeed * 37.0 + kEndSel, kSide)), kitHash(vec2(kSeed * 59.0 + kEndSel, kSide + 3.0))) - 0.5) * vec2(0.01, 0.008);
    float kx = mix(vKitA.y, abs(vKitA.y) - 0.5 * kHw, kTwo);
    vec2 kD = vec2(vKitA.x - kNa - kJ.x, kx - kJ.y);
    float kR = length(kD);
    float kHead = 1.0 - smoothstep(0.0048 - kAA * 0.7, 0.0048 + kAA * 0.7, kR);
    float kFar = smoothstep(0.004, 0.011, kAA);
    float kRs = kitNoise(kD * 300.0 + kSeed * 40.0);
    // rust + tannin stain: a dark halo, bleeding further along the grain than across it
    float kRust = (1.0 - smoothstep(0.004, 0.018 + 0.014 * kRs, length(kD * vec2(0.38, 1.0)))) * (0.5 + 0.5 * kRs);
    kC = mix(kC, kC * vec3(0.5, 0.36, 0.25), kRust * (0.4 + 0.45 * kOut) * mix(1.0, 0.6, kFar));
    // slight dent around the head (hammer rim) reads as a dark ring at low sun
    kC *= 1.0 - 0.3 * (1.0 - smoothstep(0.0, 0.0015, abs(kR - 0.0058))) * (1.0 - kFar);
    vec3 kHc = mix(vec3(0.05, 0.046, 0.043), vec3(0.2, 0.09, 0.035), kitNoise(kD * 900.0) * (0.3 + 0.6 * kOut));
    kC = mix(kC, kHc, kHead * (1.0 - kFar));
    roughnessFactor = mix(roughnessFactor, 0.55, kHead * (1.0 - kFar));
    normal = normalize(normal + (kGA * kD.x + kGX * (kD.y * mix(1.0, kSide, kTwo))) * (60.0 * kHead * (1.0 - kFar)));
  }
  // ---- end grain: growth rings around the pith (outside a flat-sawn board, inside a
  //      boxed-heart beam / post), darker and thirsty, radial splits
  if (kIsEnd > 0.5) {
    vec2 kS = vec2(vKitA.y, vKitA.x);
    float kHeart = step(5.5, kCls);
    vec2 kPi = mix(vec2((kSeed - 0.5) * 2.2 * kHw, -0.08 - 0.3 * fract(kSeed * 3.7)), (vec2(fract(kSeed * 5.3), fract(kSeed * 9.1)) - 0.5) * 0.35 * kHw, kHeart);
    vec2 kd = kS - kPi;
    float kRr = length(kd);
    float kRing = fract(kRr * (150.0 + 90.0 * fract(kSeed * 5.1)) + 0.35 * kitNoise(kS * 60.0 + kSeed * 9.0));
    float kLate = smoothstep(0.55, 0.8, kRing) * (1.0 - smoothstep(0.88, 1.0, kRing));
    kC = mix(kC, vec3(kL), 0.45) * vec3(0.66, 0.56, 0.45) * (1.0 - 0.3 * kLate);
    float kAng = atan(kd.y, kd.x);
    for (int i = 0; i < 2; i++) {
      float th = 6.2832 * kitHash(vec2(kSeed * 17.0 + float(i), 7.0));
      float da = abs(mod(kAng - th + 3.1416, 6.2832) - 3.1416) * kRr;
      float w = 0.0016 * smoothstep(0.1 * kHw, kHw, kRr) * kHeart + 0.0006 * (1.0 - kHeart) * (1.0 - float(i));
      float cr = (1.0 - smoothstep(w, w + kAA * 0.8, da)) * min(1.0, (w + 0.0002) / kAA);
      kC *= 1.0 - 0.8 * cr;
    }
    roughnessFactor = mix(roughnessFactor, 0.97, 0.7);
  }
  // board sides face into the narrow gaps between boards
  kC *= 1.0 - 0.22 * kIsBSide;
#endif

  // ---- lagoon waterline: wet film above, pale mineral ring, algae film below
  float kH = kP.y - uWaterLevel;
  if (kH < 0.5 && kOut > 0.5) {
    float kn = kitNoise(kP.xz * 9.0 + vec2(kP.y * 3.0));
    float kWet = 1.0 - smoothstep(0.02, 0.26 + 0.14 * kn, kH);
    float kSub = 1.0 - smoothstep(-0.07, 0.01, kH);
    float kq = kH - 0.1 - 0.05 * kn;
    float kRingM = exp(-kq * kq * 500.0) * (1.0 - kSub);
    kC = mix(kC, kC * 0.6, kWet * (1.0 - kSub));
    kC = mix(kC, kC * vec3(0.62, 0.7, 0.5) + vec3(0.012, 0.03, 0.01), kSub * (0.6 + 0.4 * kn));
    kC = mix(kC, vec3(0.46, 0.44, 0.4), kRingM * 0.3);
    roughnessFactor = mix(roughnessFactor, 0.35, kWet * (1.0 - kSub));
  }
  // ---- rain / dew runs on vertical faces (faint: a desert)
  float kV = 1.0 - abs(kN.y);
  if (kOut > 0.5 && kV > 0.5) {
    vec2 sp = vec2(dot(kP.xz, vec2(-kN.z, kN.x)) * 24.0, kP.y * 1.4);
    float st = smoothstep(0.6, 0.92, kitNoise(sp) * 0.65 + kitNoise(sp * vec2(2.7, 0.6) + 5.0) * 0.35);
    kC *= 1.0 - 0.1 * st * smoothstep(0.5, 1.0, kV);
  }
  // ---- cupped (edges proud) or crowned boards: each board catches the low sun on its own
  if (kIsTop > 0.5) {
    float kAx = clamp(vKitA.y / kHw, -1.0, 1.0);
    float kCup = (0.03 + 0.05 * fract(kSeed * 11.3)) * (fract(kSeed * 23.7) < 0.72 ? 1.0 : -0.7) * (0.4 + 0.6 * kOut);
    normal = normalize(normal - kGX * (kAx * kCup));
  }
  diffuseColor.rgb = max(kC, 0.0);
#ifdef KIT_WOOD_DEBUG
  // ?kitwood=1 face class, 2 wear / ground line, 3 board seed, 4 nails byte, 5 along/len
  vec3 kDbg = vec3(0.0);
  #if KIT_WOOD_DEBUG == 1
    kDbg = kHas < 0.5 ? vec3(0.2) : kCls < 1.5 ? vec3(0.9, 0.9, 0.2) : kCls < 2.5 ? vec3(0.2, 0.9, 0.2) : kCls < 3.5 ? vec3(0.9, 0.2, 0.2) : kCls < 4.5 ? vec3(0.2, 0.2, 0.9) : kCls < 5.5 ? vec3(0.2, 0.9, 0.9) : kCls < 6.5 ? vec3(0.9, 0.2, 0.9) : vec3(1.0, 0.5, 0.1);
    kDbg *= 1.0 - 0.5 * kLane;
  #elif KIT_WOOD_DEBUG == 2
    kDbg = vec3(vKitB.z / 255.0);
  #elif KIT_WOOD_DEBUG == 3
    kDbg = vec3(fract(kSeed * 7.0), fract(kSeed * 13.0), fract(kSeed * 3.0));
  #elif KIT_WOOD_DEBUG == 4
    kDbg = vec3(vKitB.y / 255.0, kNmid, 0.0);
  #else
    kDbg = vec3(fract(vKitA.x), vKitA.x / max(kLen, 0.01), 0.0);
  #endif
  diffuseColor.rgb = kDbg;
#endif
}

	#include <clearcoat_normal_fragment_begin>
	#include <clearcoat_normal_fragment_maps>
	#include <emissivemap_fragment>
	#include <lights_physical_fragment>
	#include <lagoon_lights_fragment_begin>

  reflectedLight.directDiffuse = max(reflectedLight.directDiffuse - lagoonSunDiffuse * kKitNoSun, 0.0);
  reflectedLight.directSpecular = max(reflectedLight.directSpecular - lagoonSunSpecular * kKitNoSun, 0.0);
  lagoonSunDiffuse *= 1.0 - kKitNoSun;
  lagoonSunSpecular *= 1.0 - kKitNoSun;
#include <lights_fragment_maps>

{
  vec3 lgWN = normalize( ( vec4( nonPerturbedNormal, 0.0 ) * viewMatrix ).xyz );
  float lgV = lagoonSkyVisibility( vLagoonWorldPos, lgWN );
  // mirror direction (world) of the shading normal: what the specular lobe sees
  vec3 lgRw = normalize( ( vec4( reflect( - geometryViewDir, geometryNormal ), 0.0 ) * viewMatrix ).xyz );
  vec3 lgA = vec3( uLagoonEnvScale * lgV );
  // specular: solid cover as for the diffuse, tree canopy only where the
  // reflection looks up into the crown (lagoonCanopySpecular)
  float lgCs = lagoonSolidVis * lagoonCanopySpecular( lgRw );
  vec3 lgAs = vec3( uLagoonEnvScale * ( lagoonSolidVis - lgCs ) );
  // covered sky: roofs / decks bounce warm light off the floors and ground below,
  // tree crowns pass a little dim green light through
  vec3 lgB = uSkyOccBounce * max( 1.0 - lgV - lagoonCanopyCover, 0.0 );
  #ifndef LAGOON_NO_GROUNDBOUNCE
  {
    // local ground bounce: the environment map's lower hemisphere is one uniform
    // sunlit-sand radiance (uEnvGround); swap it for the ground actually below
    float lgGM;
    vec3 lgG = lagoonGroundRadiance( vLagoonWorldPos, lgWN, lgGM );
    if ( lgGM > 0.0 ) {
      lagoonGroundMapValid = lgGM;
      vec3 lgWNs = normalize( ( vec4( geometryNormal, 0.0 ) * viewMatrix ).xyz );
      float lgGV = clamp( 0.5 - 0.5 * lgWNs.y, 0.0, 1.0 );        // view factor of the ground plane
      vec3 lgRat = lgG / max( uEnvGround, vec3( 1e-3 ) );
      #if defined( RE_IndirectDiffuse )
        iblIrradiance = max( iblIrradiance + ( LAGOON_PI * uGroundBounceParams.w * lgGV ) * ( lgG - uEnvGround ), iblIrradiance * 0.2 );
      #endif
      #if defined( RE_IndirectSpecular )
      {
        // reflections that point at the ground see the local ground too
        float lgWr = clamp( 0.5 - 1.6 * lgRw.y, 0.0, 1.0 );
        radiance *= mix( vec3( 1.0 ), clamp( lgRat, vec3( 0.05 ), vec3( 3.0 ) ), lgWr );
      }
      #endif
      // covered places (under decks, eaves): the light bounced into them comes off the ground below too
      float lgRl = dot( lgRat, vec3( 0.2126, 0.7152, 0.0722 ) );
      lgB *= mix( 1.0, clamp( lgRl, 0.3, 1.5 ), 0.6 * lgGM );
    }
  }
  #endif
  // (1 - lgV - lagoonCanopyCover = 1 - lagoonSolidVis: lgB so far is the solid cover's bounce)
  vec3 lgBs = lgB + uCanopyFill * lgCs;
  lgB += uCanopyFill * lagoonCanopyCover;
  if ( uLightDebug > 0.5 ) {
    float lgDM;
    vec3 lgDG = lagoonGroundRadiance( vLagoonWorldPos, lgWN, lgDM );
    lagoonDebugColor = uLightDebug < 1.5 ? mix( vec3( 0.0, 0.0, 0.25 ), lgDG, lgDM )
                     : uLightDebug < 2.5 ? vec3( lgV + lagoonCanopyCover, 1.0 - lagoonCanopyCover, lgV )
                     : uLightDebug < 3.5 ? vec3( lagoonMaskAt( vLagoonWorldPos ) )
                     : vec3( lagoonSolidVis - lgCs, 1.0 - lgCs, lagoonSolidVis );
  }
  float lgUM = lagoonUnderwaterMask( vLagoonWorldPos );
  vec3 lgW = lgUM > 0.0 ? mix( vec3( 1.0 ), 0.9 * exp( -uWaterAbsorb * ( ( uWaterLevel - vLagoonWorldPos.y ) * 1.25 ) ), lgUM ) : vec3( 1.0 );
  lgA *= lgW;
  lgB *= lgW;
  lgAs *= lgW;
  lgBs *= lgW;
  #if defined( RE_IndirectDiffuse )
    irradiance *= lgW;
  #endif
  #if defined( RE_IndirectDiffuse )
    iblIrradiance = iblIrradiance * lgA + lgB;
  #endif
  #if defined( RE_IndirectSpecular )
    {
      // horizon (specular) occlusion: a normal-mapped groove whose reflection
      // vector dips below the geometric surface reflects the surface itself, not
      // the sky - bark furrows, plank gaps and thatch strands must not glow
      float lgHz = clamp( 1.0 + 1.2 * dot( reflect( - geometryViewDir, geometryNormal ), nonPerturbedNormal ), 0.0, 1.0 );
      radiance *= mix( 1.0, lgHz * lgHz, uLightFx.z );
    }
    radiance = radiance * lgAs + lgBs * ( 1.0 / LAGOON_PI );
    #ifdef USE_CLEARCOAT
      clearcoatRadiance *= lgAs;
    #endif
  #endif
}
#include <lights_fragment_end>

	#include <aomap_fragment>

#if defined( USE_AOMAP ) && !defined( USE_ALPHATEST ) && !defined( ALPHA_TO_COVERAGE )
if ( uLightFx.x > 0.0 ) {
  // relief cavities only: the texel's AO relative to the map's local mean (a
  // coarse mip), so broad grime / weathering baked into the AO does not dim a
  // whole plank face under the grazing sun - only gaps, grooves and weave do
  float lgAoMean = ( textureLod( aoMap, vAoMapUv, 6.0 ).r - 1.0 ) * aoMapIntensity + 1.0;
  float lgAoRel = clamp( ambientOcclusion / max( lgAoMean, 0.05 ), 0.0, 1.0 );
  float lgNoL = clamp( dot( normal, lagoonSunDirView ), 0.0, 1.0 );
  float lgAp = inversesqrt( max( 1.0 - lgAoRel, 1e-4 ) );
  float lgMs = clamp( lgNoL * lgAp, 0.0, 1.0 );
  lgMs = 1.0 - uLightFx.x * ( 1.0 - lgMs * lgMs );
  reflectedLight.directDiffuse -= lagoonSunDiffuse * ( 1.0 - lgMs );
  reflectedLight.directSpecular -= lagoonSunSpecular * ( 1.0 - lgMs );
}
#endif

	vec3 totalDiffuse = reflectedLight.directDiffuse + reflectedLight.indirectDiffuse;
	vec3 totalSpecular = reflectedLight.directSpecular + reflectedLight.indirectSpecular;
	#include <transmission_fragment>
	vec3 outgoingLight = totalDiffuse + totalSpecular + totalEmissiveRadiance;
	#ifdef USE_SHEEN

		outgoingLight = outgoingLight + sheenSpecularDirect + sheenSpecularIndirect;

 	#endif
	#ifdef USE_CLEARCOAT
		float dotNVcc = saturate( dot( geometryClearcoatNormal, geometryViewDir ) );
		vec3 Fcc = F_Schlick( material.clearcoatF0, material.clearcoatF90, dotNVcc );
		outgoingLight = outgoingLight * ( 1.0 - material.clearcoat * Fcc ) + ( clearcoatSpecularDirect + clearcoatSpecularIndirect ) * material.clearcoat;
	#endif
	outgoingLight += lagoonExtraLight(diffuseColor.rgb, vLagoonWorldPos, normalize((vec4(normal, 0.0) * viewMatrix).xyz));
#include <opaque_fragment>
	#include <tonemapping_fragment>
	#include <colorspace_fragment>
	gl_FragColor.rgb = uLightDebug > 0.5 ? lagoonDebugColor : lagoonAtmosphere(gl_FragColor.rgb, vLagoonWorldPos);
	#include <premultiplied_alpha_fragment>
	#include <dithering_fragment>
}

