  float kIsRound = kHas * (1.0 - step(0.5, abs(kCls - 5.0)));
  float kIsEnd = kHas * max(1.0 - step(0.5, abs(kCls - 3.0)), 1.0 - step(0.5, abs(kCls - 6.0)));
