materials.vertexShader:
#define STANDARD
varying vec3 vViewPosition;
#ifdef USE_TRANSMISSION
	varying vec3 vWorldPosition;
#endif
#include <common>
varying vec3 vLagoonWorldPos;


attribute vec4 kitA;
