  float kWear = vKitB.z * (1.0 / 255.0) * kIsTop;
  kWear = max(kWear, kLane * kIsTop * 0.85 * (1.0 - smoothstep(0.14, 0.42, abs(vKitA.x / max(kLen, 0.01) - 0.5))));
